import java.util.Arrays;

class Solution {
    private int ans;

    private void backtrack(int idx, int[] jobs, int[] workers, int k) {
        if (idx == jobs.length) {
            int mx = 0;
            for (int w : workers) mx = Math.max(mx, w);
            ans = Math.min(ans, mx);
            return;
        }
        int job = jobs[idx];
        for (int i = 0; i < k; ++i) {
            if (workers[i] + job >= ans) continue;
            workers[i] += job;
            backtrack(idx + 1, jobs, workers, k);
            workers[i] -= job;
            if (workers[i] == 0) break;
        }
    }

    public int minimumTimeRequired(int[] jobs, int k) {
        Arrays.sort(jobs);
        for (int i = 0, j = jobs.length - 1; i < j; ++i, --j) {
            int t = jobs[i]; jobs[i] = jobs[j]; jobs[j] = t;
        }
        int[] workers = new int[k];
        ans = 0;
        for (int j : jobs) ans += j;
        backtrack(0, jobs, workers, k);
        return ans;
    }
}

