var minimumTimeRequired = function(jobs, k) {
    jobs.sort((a, b) => b - a);
    const workers = Array(k).fill(0);
    let ans = jobs.reduce((a, b) => a + b, 0);

    function backtrack(idx) {
        if (idx === jobs.length) {
            ans = Math.min(ans, Math.max(...workers));
            return;
        }
        const job = jobs[idx];
        for (let i = 0; i < k; ++i) {
            if (workers[i] + job >= ans) continue;
            workers[i] += job;
            backtrack(idx + 1);
            workers[i] -= job;
            if (workers[i] === 0) break;
        }
    }

    backtrack(0);
    return ans;
};
